import { ValidationError } from '../errors/DomainErrors';

export const TASK_STATUS_VALUES = ['todo', 'in_progress', 'done'] as const;

export type TaskStatusValue = (typeof TASK_STATUS_VALUES)[number];

export class TaskStatus {
  static readonly TODO = new TaskStatus('todo');
  static readonly IN_PROGRESS = new TaskStatus('in_progress');
  static readonly DONE = new TaskStatus('done');

  private constructor(readonly value: TaskStatusValue) {}

  static from(value: string): TaskStatus {
    switch (value) {
      case 'todo':
        return TaskStatus.TODO;
      case 'in_progress':
        return TaskStatus.IN_PROGRESS;
      case 'done':
        return TaskStatus.DONE;
      default:
        throw new ValidationError(
          `Invalid task status '${value}'. Expected one of: ${TASK_STATUS_VALUES.join(', ')}`,
        );
    }
  }

  isDone(): boolean {
    return this.value === 'done';
  }

  equals(other: TaskStatus): boolean {
    return this.value === other.value;
  }
}

